  what_to_expect = '{"primaryOutcome":{"label":"Stress Support","timeframe":"4-8 weeks","intensity":"Moderate"},"secondaryOutcome":{"label":"Sleep Quality","timeframe":"6-12 weeks","intensity":"Low to Moderate"}}'::jsonb,
