-- ===== BCAAs (bcaas) =====
UPDATE api.supplements SET
  quick_overview = 'Branched-chain amino acids (leucine, isoleucine, valine) are essential nutrients that support muscle protein synthesis. Popular among athletes and fitness enthusiasts.',
  extended_overview = 'BCAAs represent three of the nine essential amino acids that humans must obtain through diet or supplementation, as the body cannot synthesize them independently. Unlike other amino acids that are metabolized primarily in the liver, BCAAs are uniquely metabolized directly in muscle tissue, making them particularly relevant for athletes and those engaged in regular physical training. Leucine, often considered the most important of the three, acts as a key trigger for muscle protein synthesis through its activation of the mTOR pathway—a cellular signaling mechanism that initiates the building of new muscle proteins. Isoleucine plays a role in glucose uptake into cells and energy production during exercise, while valine contributes to muscle metabolism and nitrogen balance. The popularity of BCAA supplements in the fitness community stems from their targeted delivery of these specific amino acids without the caloric load of whole protein sources, making them particularly appealing for those training in fasted states or seeking to minimize caloric intake while supporting muscle preservation.',
  science_snapshot = 'Research on BCAAs has produced mixed results, with some studies showing benefits for reducing muscle soreness and perceived exertion during exercise, while others suggest that adequate total protein intake may diminish the need for isolated BCAA supplementation. The most consistent findings relate to their role in reducing exercise-induced muscle damage markers and supporting recovery in endurance athletes or those training at high volumes.',
  key_benefits = ARRAY['Supports muscle protein synthesis','May reduce exercise-induced fatigue','Essential amino acid supplementation','Popular for workout recovery','May help preserve lean muscle during caloric restriction','Supports endurance during prolonged exercise'],
  ideal_for = ARRAY['Athletes and active individuals','Those doing resistance training','People with higher protein needs','Endurance athletes training at high volumes','Those training in fasted states'],
  timing_tips = ARRAY['Often taken around workouts','Can be consumed throughout the day','Some prefer intra-workout consumption','Pre-workout dosing may help with energy during training'],
  quality_markers = ARRAY['2:1:1 ratio','instantized','fermented','leucine content'],
  safety_considerations = ARRAY['Generally well-tolerated at recommended doses','Those with maple syrup urine disease should avoid BCAA supplements','May affect blood sugar levels; diabetics should monitor accordingly'],
  what_to_expect_summary = ARRAY['Many users notice reduced muscle soreness within the first week or two of consistent use around training','Recovery benefits typically become more apparent after 2-4 weeks of regular supplementation','Effects may be most noticeable during high-volume training phases or caloric restriction','Those already consuming adequate protein may experience less dramatic effects'],
  typical_dosage_min = 5000,
  typical_dosage_max = 10000,
  typical_dosage_unit = 'mg',
  form_notes = '{"powder":"Mix with water, customizable serving size","capsule":"Convenient, no mixing required","tablet":"Portable, precise dosing"}'::jsonb,
  what_to_expect = '{"primaryOutcome":{"label":"Recovery Support","timeframe":"2-4 weeks","intensity":"Moderate"},"secondaryOutcome":{"label":"Reduced Muscle Soreness","timeframe":"1-2 weeks","intensity":"Low to Moderate"}}'::jsonb,
  synergy_notes = 'BCAAs are often stacked with other performance supplements like creatine, beta-alanine, or citrulline for comprehensive workout support. They can complement a whey protein regimen for those seeking targeted intra-workout amino acid delivery.'
